import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';

/** Processing attempts allowed in total, including the first. */
export const MAX_ATTEMPTS = 3;
/** Simulated duration of one step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
export const RETRY_DELAY_MS = 500;
/** A running job whose lease has lapsed is treated as orphaned and requeued. Renewed on every step. */
export const LEASE_MS = 5_000;
/** The worker is "up" if its heartbeat is at most this old. */
export const HEARTBEAT_FRESH_MS = 3_000;
/** How often the worker writes its heartbeat. */
export const HEARTBEAT_EVERY_MS = 1_000;
export const TRANSIENT_ERROR = 'transient failure';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  /** JSON-encoded input (see encodeText). */
  input_json: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  /** JSON-encoded output (see encodeText), or null. */
  result_json: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  lease_until: number | null;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

