 * SQLite TEXT cannot hold every JS string losslessly (NUL bytes are truncated, lone surrogates become
 * U+FFFD), so user text is stored as JSON, which escapes both. Decode it with decodeText.
 */
export const encodeText = (s: string): string => JSON.stringify(s);
export const decodeText = (s: string): string => JSON.parse(s) as string;

export function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: decodeText(r.input_json),
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result_json !== null ? { output: decodeText(r.result_json) } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

