    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

const iso = (ms: number): string => new Date(ms).toISOString();

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function findJobRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first. */
export function listJobRows(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export function insertJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | null, now = Date.now()): JobRow {
  const id = randomUUID();
  const ts = iso(now);
  db.prepare(
    `INSERT INTO jobs (id, status, input_json, steps, fail_attempts, attempts, progress_completed,
                       idempotency_key, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(id, encodeText(job.input), job.steps, job.failAttempts, idempotencyKey, ts, ts);
  return getJobRow(db, id)!;
}

/**
 * Claims the oldest queued job that is due, marking it running and starting a new attempt.
 * Returns the claimed row, with `attempts` already incremented.
 */
export function claimNextJob(db: DatabaseSync, now: number): JobRow | undefined {
  return transaction(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? AND attempts < ? ORDER BY seq LIMIT 1`)
      .get(now, MAX_ATTEMPTS) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0,
                       lease_until = ?, updated_at = ?
       WHERE id = ? AND attempts < ?`,
    ).run(now + LEASE_MS, iso(now), next.id, MAX_ATTEMPTS);
    return getJobRow(db, next.id);
  });
}

/**
 * Requeues running jobs whose worker stopped renewing their lease (for example after SIGKILL).
 * The interrupted attempt did not finish, so it is uncounted and the same attempt number runs again.
 * This keeps `attempts` within MAX_ATTEMPTS and lets interrupted jobs still finish.
 */
export function recoverExpiredJobs(db: DatabaseSync, now: number): number {
  const result = db
    .prepare(
      `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0,
                       attempts = MAX(attempts - 1, 0), lease_until = NULL, updated_at = ?
       WHERE status = 'running' AND lease_until < ?`,
    )
    .run(iso(now), now);
  return Number(result.changes);
}

export function renewProgress(db: DatabaseSync, id: string, completed: number, now: number): void {
  db.prepare(
    `UPDATE jobs SET progress_completed = ?, lease_until = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(completed, now + LEASE_MS, iso(now), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_json = ?, error = NULL,
                     progress_completed = steps, lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(encodeText(output), iso(now), id);
}

export function failJob(db: DatabaseSync, id: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', error = ?, result_json = NULL,
                     progress_completed = 0, lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(TRANSIENT_ERROR, iso(now), id);
}

export function scheduleRetry(db: DatabaseSync, id: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?,
                     lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(now + RETRY_DELAY_MS, iso(now), id);
}

/** Returns a running job to the queue without counting it as failed (used on shutdown). */
export function releaseJob(db: DatabaseSync, id: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0,
                     lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(iso(now), id);
}

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    `INSERT INTO heartbeats (name, seen_at) VALUES ('worker', ?)
     ON CONFLICT(name) DO UPDATE SET seen_at = excluded.seen_at`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
}

export function workerLastSeen(db: DatabaseSync): number | undefined {
  const row = db.prepare(`SELECT seen_at FROM heartbeats WHERE name = 'worker'`).get() as { seen_at: number } | undefined;
  return row?.seen_at;
}

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  migrate(db);
  return db;
}

function migrate(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq                INTEGER PRIMARY KEY AUTOINCREMENT,
      id                 TEXT NOT NULL UNIQUE,
      status             TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      input              TEXT NOT NULL,
      steps              INTEGER NOT NULL,
      fail_attempts      INTEGER NOT NULL,
      attempts           INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0,
      result_output      TEXT,
      error              TEXT,
      idempotency_key    TEXT UNIQUE,
      available_at       INTEGER NOT NULL DEFAULT 0,
      lease_until        INTEGER,
      created_at         TEXT NOT NULL,
      updated_at         TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
    CREATE TABLE IF NOT EXISTS heartbeats (
      name    TEXT PRIMARY KEY,
      seen_at INTEGER NOT NULL
    );
  `);
}

/** Runs `fn` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front, so read-then-write is atomic across processes. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, transaction } from './db.ts';
import {
  findJobRowByKey,
  getJobRow,
  HEARTBEAT_FRESH_MS,
  insertJob,
  listJobRows,
  toJob,
  workerLastSeen,
  type JobRow,
  type NewJob,
} from './jobs.ts';
import { MAX_BODY_BYTES, parseSubmission, type FieldError } from './validation.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function health(): { status: 'ok'; worker: 'up' | 'down' } {
  const seen = workerLastSeen(db);
  const up = seen !== undefined && Date.now() - seen <= HEARTBEAT_FRESH_MS;
  return { status: 'ok', worker: up ? 'up' : 'down' };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const header = req.headers['idempotency-key'];
  const parsed = parseSubmission({
    body: text,
    bodyTooLarge: tooLarge,
    contentType: req.headers['content-type'],
    idempotencyKey: Array.isArray(header) ? header.join(', ') : header,
  });
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', parsed.fields);
    return;
  }

  const { job, idempotencyKey } = parsed;
  if (idempotencyKey === null) {
    sendJson(res, 201, toJob(insertJob(db, job, null)));
    return;
  }

  // The lookup and insert share one write transaction, so a key can never produce two jobs.
  const outcome = transaction(db, (): { status: 200 | 201; row: JobRow } | null => {
    const existing = findJobRowByKey(db, idempotencyKey);
    if (!existing) return { status: 201, row: insertJob(db, job, idempotencyKey) };
    return sameSubmission(existing, job) ? { status: 200, row: existing } : null;
  });

  if (outcome === null) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different submission.');
    return;
  }
  sendJson(res, outcome.status, toJob(outcome.row));
}

function sameSubmission(row: JobRow, job: NewJob): boolean {
  return row.input === job.input && row.steps === job.steps && row.fail_attempts === job.failAttempts;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? 'GET';

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    sendJson(res, 200, health());
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') {
      sendJson(res, 200, { jobs: listJobRows(db).map(toJob) });
      return;
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const row = getJobRow(db, decodeSegment(match[1]!));
    if (!row) return sendError(res, 404, 'not_found', 'No job has that id.');
    sendJson(res, 200, toJob(row));
    return;
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

function decodeSegment(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Unexpected server error.');
  });
});

server.on('error', (e) => {
  console.error(`server failed to listen on ${port}: ${e.message}`);
  process.exit(1);
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

